const input = $input.first().json || {};

function nowIso() {
  return new Date().toISOString();
}

function getByPath(obj, path) {
  if (!obj || !path) return undefined;
  return String(path).split(".").reduce((acc, key) => {
    if (acc === undefined || acc === null) return undefined;
    return acc[key];
  }, obj);
}

function normalizeString(value) {
  if (value === undefined || value === null) return "";
  return String(value).trim();
}

function normalizeEmail(value) {
  return normalizeString(value).toLowerCase();
}

function normalizeConsent(value, defaultConsentStatus = "not_provided") {
  if (value === true) return "opted_in";
  if (value === false) return "not_provided";

  const normalized = normalizeString(value).toLowerCase();
  if (!normalized) return defaultConsentStatus;

  const optedIn = ["yes", "true", "opted_in", "consented", "subscribed", "i agree", "agree"];
  const optedOut = ["no", "false", "opted_out", "unsubscribed", "do_not_contact"];

  if (optedIn.includes(normalized)) return "opted_in";
  if (optedOut.includes(normalized)) return "opted_out";

  return normalized;
}

function extractTypeformAnswer(payload, ref) {
  const answers = payload?.form_response?.answers;
  if (!Array.isArray(answers)) return undefined;

  const answer = answers.find(item => item?.field?.ref === ref);
  if (!answer) return undefined;

  if (answer.text !== undefined) return answer.text;
  if (answer.email !== undefined) return answer.email;
  if (answer.phone_number !== undefined) return answer.phone_number;
  if (answer.url !== undefined) return answer.url;
  if (answer.boolean !== undefined) return answer.boolean;
  if (answer.choice?.label !== undefined) return answer.choice.label;
  if (answer.number !== undefined) return answer.number;

  return undefined;
}

function valueFromMap(payload, sourcePath, typeformRefMode = false) {
  if (!sourcePath) return undefined;

  if (typeformRefMode) {
    return extractTypeformAnswer(payload, sourcePath);
  }

  return getByPath(payload, sourcePath);
}

function fail({ code, message, details = [] }) {
  return [
    {
      json: {
        success: false,
        component_id: "C2-E",
        component_version: "v1",
        event_id: input.input?.event_id || null,
        event_type: input.input?.event_type || null,
        normalized_payload: null,
        c2f_handoff: null,
        source_result: input.input || {},
        error: {
          code,
          message,
          details
        },
        next_action: "route_to_failure_log"
      }
    }
  ];
}

if (!input || Object.keys(input).length === 0) {
  return fail({
    code: "EMPTY_INPUT",
    message: "Input object is empty."
  });
}

if (!input.input || typeof input.input !== "object") {
  return fail({
    code: "MISSING_INPUT_OBJECT",
    message: "Input must include an input object."
  });
}

const source = input.input;
const config = input.config || {};
const payload = source.payload || {};

if (source.success !== true) {
  return fail({
    code: "UPSTREAM_ACTION_FAILED",
    message: "C2-E will not normalize form intake when upstream action failed.",
    details: [
      {
        upstream_component: source.component_id || null,
        upstream_error: source.error || null
      }
    ]
  });
}

if (source.next_action !== "normalize_form_intake") {
  return fail({
    code: "FORM_INTAKE_NOT_REQUESTED",
    message: "source.next_action is not normalize_form_intake.",
    details: [{ next_action: source.next_action || null }]
  });
}

if (!config.field_map || typeof config.field_map !== "object") {
  return fail({
    code: "MISSING_FIELD_MAP",
    message: "config.field_map is required."
  });
}

const fieldMap = config.field_map;
const typeformRefMode = config.typeform_ref_mode === true;

const rawConsent =
  valueFromMap(payload, fieldMap.consent_status, typeformRefMode) ??
  valueFromMap(payload, fieldMap.consent, typeformRefMode);

const normalizedPayload = {
  name: normalizeString(valueFromMap(payload, fieldMap.name, typeformRefMode)),
  email: normalizeEmail(valueFromMap(payload, fieldMap.email, typeformRefMode)),
  phone: normalizeString(valueFromMap(payload, fieldMap.phone, typeformRefMode)),
  company: normalizeString(valueFromMap(payload, fieldMap.company, typeformRefMode)),
  website: normalizeString(valueFromMap(payload, fieldMap.website, typeformRefMode)),
  message: normalizeString(valueFromMap(payload, fieldMap.message, typeformRefMode)),
  source: config.form_source || source.metadata?.origin || "form_submission",
  consent_status: normalizeConsent(rawConsent, config.default_consent_status || "not_provided"),
  submitted_at: source.metadata?.submitted_at || nowIso()
};

const emptyFields = Object.entries(normalizedPayload)
  .filter(([key, value]) => ["name", "email", "phone", "company", "website", "message"].includes(key) && !value)
  .map(([key]) => key);

const c2fHandoff = {
  next_component: "C2-F",
  input: {
    success: true,
    component_id: "C2-E",
    component_version: "v1",
    event_id: source.event_id || null,
    event_type: "normalized_form_intake",
    payload: normalizedPayload,
    metadata: {
      source_component: source.component_id || null,
      original_event_type: source.event_type || null,
      form_source: config.form_source || null,
      empty_fields: emptyFields,
      normalized_at: nowIso()
    },
    error: null,
    next_action: "validate_payload"
  },
  config: {
    validation_rules: config.validation_rules || {
      required_fields: ["name", "email", "message"],
      email_fields: ["email"]
    },
    default_next_action: "dedupe_check"
  }
};

return [
  {
    json: {
      success: true,
      component_id: "C2-E",
      component_version: "v1",
      event_id: source.event_id || null,
      event_type: source.event_type || null,
      normalized_payload: normalizedPayload,
      c2f_handoff: c2fHandoff,
      source_result: source,
      error: null,
      next_action: config.default_next_action || "validate_payload"
    }
  }
];
